class Solution {
public:
    vector<string> letterCombinations(string digits) {
        if (digits.empty()) return {};
        vector<string> res;
        string cur;
        vector<string> map = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};

        function<void(int)> backtrack = [&](int i) {
            if (i == digits.size()) {
                res.push_back(cur);
                return;
            }
            for (char c : map[digits[i] - '0']) {
                cur.push_back(c);
                backtrack(i + 1);
                cur.pop_back();
            }
        };

        backtrack(0);
        return res;
    }
};
